<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\{Support,Municipalities,Dispatch};
class TransferController extends Controller {
 private function center(){abort_unless(auth()->user()->role==='sorting_center',403);$c=DB::table('sorting_centers')->where('user_id',auth()->id())->first();abort_unless($c,403);return $c;}
 public function index(){
  $c=$this->center();\App\Services\BulkTrips::refresh();DB::table('assignments')->where('kind','transfer')->where('status','offered')->whereNull('trip_id')->where('expires_at','<=',now())->update(['status'=>'expired','updated_at'=>now()]);
  $rows=DB::table('parcels')->where('center_id',$c->id)->whereIn('status',['AT_SORTING_CENTER','SORTED','TRANSFER_OFFERED','IN_TRANSIT_CENTER'])->orderByDesc('id')->get()->filter(fn($p)=>in_array($p->status,['TRANSFER_OFFERED','IN_TRANSIT_CENTER'])||!\App\Services\ProcessRouting::local($p));
  $offers=[];$destinations=[];foreach($rows as $p){$offers[$p->id]=DB::table('assignments')->where('parcel_id',$p->id)->where('kind','transfer')->whereIn('status',['offered','accepted'])->orderByDesc('id')->first();$destinations[$p->id]=\App\Services\ProcessRouting::destination($p);}
  return view('transfers',['links'=>app(CommonController::class)->links(),'bulkSelectable'=>$rows->filter(fn($p)=>in_array($p->status,['AT_SORTING_CENTER','SORTED'])&&$destinations[$p->id]&&$destinations[$p->id]->id!==$c->id&&!DB::table('assignments')->where('parcel_id',$p->id)->whereIn('status',['offered','accepted','requested'])->exists())->take(100),
 'trips'=>DB::table('driver_trips')->where('origin_center_id',$c->id)->whereIn('status',['offered','accepted','in_transit'])->orderByDesc('id')->get()->map(fn($t)=>DriverTripController::manifest($t)),
 'bulkIncoming'=>DB::table('driver_trip_stops as s')->join('driver_trips as t','t.id','=','s.trip_id')->where('s.center_id',$c->id)->whereNull('s.received_at')->whereIn('t.status',['offered','accepted','in_transit'])->select('t.*')->distinct()->get()->map(fn($t)=>DriverTripController::manifest($t,$c->id)),
 'parcels'=>\App\Services\ProcessRouting::paginate($rows->reject(fn($p)=>DB::table('assignments')->where('parcel_id',$p->id)->whereNotNull('trip_id')->whereIn('status',['offered','accepted'])->exists())->values()),'offers'=>$offers,'destinations'=>$destinations,'incoming'=>DB::table('parcels')->whereNotIn('id',DB::table('assignments')->whereNotNull('trip_id')->whereIn('status',['offered','accepted'])->select('parcel_id'))->where('destination_center_id',$c->id)->whereIn('status',['TRANSFER_OFFERED','IN_TRANSIT_CENTER'])->get(),'drivers'=>DB::table('users')->where('company_id',auth()->id())->where('role','rider')->where('courier_type','driver')->where('active',1)->where('account_status','active')->where('approval_status','approved')->where('online',1)->where('last_seen_at','>',now()->subMinutes(30))->get()->filter(fn($u)=>\App\Services\BulkTrips::workload($u->id)<3)]);
 }
 public function offer(Request $r,int $id){$c=$this->center();$v=$r->validate(['rider_id'=>'required|integer']);DB::transaction(function()use($id,$c,$v){$p=DB::table('parcels')->where('id',$id)->where('center_id',$c->id)->lockForUpdate()->first();abort_unless($p,404);if(DB::table('assignments')->where('parcel_id',$id)->whereNotNull('trip_id')->whereIn('status',['offered','accepted'])->exists())Support::fail('trip','This parcel belongs to a bulk trip. Manage that trip instead.');if(!in_array($p->status,['AT_SORTING_CENTER','SORTED','TRANSFER_OFFERED']))Support::fail('parcel','Receive the parcel before transferring it.');$o=DB::table('orders')->find($p->order_id);$a=$o->address_snapshot?json_decode($o->address_snapshot):DB::table('addresses')->find($o->address_id);$destination=Municipalities::centerFor($a);if(!$destination||$destination->id===$c->id)Support::fail('destination','No different approved sorting center serves the buyer municipality.');
 $u=DB::table('users')->where('id',$v['rider_id'])->where('company_id',auth()->id())->lockForUpdate()->first();abort_unless($u,403);Municipalities::courier($u,$p,'transfer');if(!$u->online||!$u->last_seen_at||now()->diffInMinutes($u->last_seen_at,true)>=30)Support::fail('rider_id','Driver must be Online.');if(\App\Services\BulkTrips::workload($u->id)>=3)Support::fail('rider_id','Driver is at capacity.');if(DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('status','accepted')->exists())Support::fail('parcel','A driver already accepted this transfer.');
 DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('status','offered')->update(['status'=>'reassigned','updated_at'=>now()]);
 DB::table('assignments')->insert(['parcel_id'=>$id,'rider_id'=>$u->id,'kind'=>'transfer','status'=>'offered','expires_at'=>now()->addMinutes(5),'earnings'=>50,'created_at'=>now(),'updated_at'=>now()]);DB::table('parcels')->where('id',$id)->update(['delivery_area_id'=>null,'destination_center_id'=>$destination->id,'status'=>'TRANSFER_OFFERED','updated_at'=>now()]);DB::table('orders')->where('id',$p->order_id)->update(['status'=>'TRANSFER_OFFERED','updated_at'=>now()]);$this->history($p,'TRANSFER_OFFERED','Transfer to '.$destination->name);Support::notify([$u->id,$destination->user_id],"Center transfer offered for {$p->tracking_code} to {$destination->name}.");});return back()->with('success','Transfer offered to driver.');}
 public function depart(int $id){$bulk=DB::table('assignments')->where('parcel_id',$id)->where('rider_id',auth()->id())->whereNotNull('trip_id')->where('status','accepted')->first();if($bulk){\App\Services\BulkTrips::depart($bulk->trip_id,auth()->id());return request()->expectsJson()?response()->json(['message'=>'Bulk trip departed.']):redirect('/driver/trips?tab=progress');}abort_unless(auth()->user()->role==='rider'&&auth()->user()->courier_type==='driver',403);DB::transaction(function()use($id){$p=DB::table('parcels')->where('id',$id)->lockForUpdate()->first();abort_unless($p&&$p->status==='TRANSFER_OFFERED'&&$p->destination_center_id,422);$a=DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('rider_id',auth()->id())->where('status','accepted')->lockForUpdate()->first();abort_unless($a,403);Municipalities::courier(auth()->user(),$p,'transfer');DB::table('parcels')->where('id',$id)->update(['status'=>'IN_TRANSIT_CENTER','updated_at'=>now()]);DB::table('orders')->where('id',$p->order_id)->update(['status'=>'IN_TRANSIT_CENTER','updated_at'=>now()]);$this->history($p,'IN_TRANSIT_CENTER','Driver departed source sorting center.');});return request()->expectsJson()?response()->json(['message'=>'Transfer departed.']):back()->with('success','Transfer departed. Destination center must confirm receipt.');}
 public function handover(Request $r,int $id){
  $r->validate(['confirm_handover'=>'accepted']);$u=auth()->user();abort_unless($u->role==='rider'&&$u->courier_type==='driver'&&$u->active&&$u->account_status==='active'&&$u->approval_status==='approved',403);
  $a=DB::table('assignments')->where('parcel_id',$id)->where('rider_id',$u->id)->where('kind','transfer')->where('status','accepted')->first();abort_unless($a,403);
  if($a->trip_id){$item=DB::table('driver_trip_items')->where('assignment_id',$a->id)->first();\App\Services\BulkTrips::handover($item->stop_id,$u->id);}
  else DB::transaction(function()use($a,$u,$id){$p=DB::table('parcels')->where('id',$id)->lockForUpdate()->first();abort_unless($p&&$p->status==='IN_TRANSIT_CENTER',422);$locked=DB::table('assignments')->where('id',$a->id)->lockForUpdate()->first();abort_unless($locked->status==='accepted',422);if($locked->handed_over_at)return;DB::table('assignments')->where('id',$a->id)->update(['handed_over_at'=>now(),'handed_over_by'=>$u->id,'updated_at'=>now()]);Support::audit('driver-handover','parcel',$id,null,['driver_id'=>$u->id]);});
  return $r->expectsJson()?response()->json(['message'=>'Handover recorded; awaiting center confirmation.']):back()->with('success','Handover recorded; awaiting center confirmation.');
 }
 public function receive(int $id){request()->validate(['confirm_receipt'=>'accepted']);$c=$this->center();$bulk=DB::table('driver_trip_items as i')->join('driver_trips as t','t.id','=','i.trip_id')->where('i.parcel_id',$id)->whereIn('t.status',['in_transit','completed'])->orderByDesc('i.id')->select('i.*')->first();if($bulk){\App\Services\BulkTrips::receive($bulk->stop_id,auth()->id(),[$id]);return redirect('/center/delivery')->with('success','Parcel received from bulk trip.');}DB::transaction(function()use($id,$c){$p=DB::table('parcels')->where('id',$id)->where('destination_center_id',$c->id)->lockForUpdate()->first();abort_unless($p&&$p->status==='IN_TRANSIT_CENTER',422);$handover=DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('status','accepted')->lockForUpdate()->first();if(!$handover||!$handover->handed_over_at||$handover->handed_over_by!=$handover->rider_id)Support::fail('handover','The assigned driver must confirm handover before your center can confirm receipt.');DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('status','accepted')->update(['status'=>'completed','received_by'=>auth()->id(),'updated_at'=>now()]);Support::audit('center-receipt','parcel',$id,null,['receiver_id'=>auth()->id(),'driver_id'=>$handover->rider_id]);DB::table('parcels')->where('id',$id)->update(['center_id'=>$c->id,'destination_center_id'=>null,'delivery_area_id'=>null,'status'=>'AT_SORTING_CENTER','updated_at'=>now()]);DB::table('orders')->where('id',$p->order_id)->update(['status'=>'AT_SORTING_CENTER','updated_at'=>now()]);$this->history($p,'AT_SORTING_CENTER','Destination sorting center confirmed receipt.');Support::notify([$c->user_id],"Parcel {$p->tracking_code} received; sort for local delivery.");});return redirect('/center/delivery')->with('success','Parcel received. It is now in Deliveries; assign the local area rider.');}
 private function history($p,string $status,string $reason){DB::table('status_history')->insert(['parcel_id'=>$p->id,'from_status'=>$p->status,'to_status'=>$status,'actor_id'=>auth()->id(),'reason'=>$reason,'created_at'=>now(),'updated_at'=>now()]);Support::audit('center-transfer','parcel',$p->id,$p,['status'=>$status],$reason);}
}
